/* eslint-disable no-undef */
import { Component, Element, Event, EventEmitter, h, Host, Listen, Prop } from '@stencil/core';
import { Alignment, IndicatorDesign, Order, OrderEvent } from '../../../types';

/**
 * @slot default - default slot for the content of the cell
 */
@Component({
  tag: 'groupui-table-cell',
  styleUrl: 'table-cell.scss',
  shadow: true,
})
export class TableCell {
  /**
   * defines a cell as sortable
   */
  @Prop({ reflect: true }) readonly sortable: boolean;

  /**
   * sets the icon for the indicator
   */
  @Prop({ reflect: true }) readonly indicator: IndicatorDesign = 'default';

  /**
   * defines the direction of the sorting-icon (default is down and only available in conjunction with sortable). Set the order to implement your own sorting logic.
   */
  @Prop({ reflect: true }) readonly order: Order = 'unsorted';

  /**
   * defines the number of columns a cell should span
   */
  @Prop({ reflect: true }) readonly colspan: number;

  /**
   * defines the alignment of the cell. If the cell is part of a header row, the alignment of the whole column is set.
   */
  @Prop({ reflect: true }) readonly alignment: Alignment = 'left';

  /**
   * defines a cell as highlighted
   */
  @Prop({ reflect: true }) readonly highlighted: boolean = false;

  /**
   * dispatched when the sort icon is clicked => 'event.details' delivers the property order and the index (HINT: on event dispatched sortable logic has to be implemented by yourself)
   */
  @Event() groupuiSortClick: EventEmitter<OrderEvent>;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @Element() host: HTMLElement;

  private static HOVER_CSS_CLASS = 'hover';

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  @Listen('click')
  handleSortIconClick() {
    if (this.sortable) {
      let indexOfThisElement = -1;
      this.host.parentElement.querySelectorAll('groupui-table-cell').forEach((cell, index) => {
        if (cell.isSameNode(this.host)) {
          indexOfThisElement = index;
        }
      });
      this.groupuiSortClick.emit({ index: indexOfThisElement, order: this.order });
    }
  }

  @Listen('mouseover')
  handleMouseover() {
    this.handleHoverClass(false);
  }

  @Listen('mouseleave')
  handleMouseleave() {
    this.handleHoverClass(true);
  }

  private getCurrentRowIndex() {
    return this.host.getAttribute('row');
  }

  private handleHoverClass(remove: boolean) {
    const rowIndex = this.getCurrentRowIndex();
    this.host.parentElement
      .querySelectorAll(`groupui-table-cell[row='${rowIndex}']`)
      .forEach((cell: HTMLGroupuiTableCellElement) => {
        if (remove) {
          cell.classList.remove(TableCell.HOVER_CSS_CLASS);
        } else {
          cell.classList.add(TableCell.HOVER_CSS_CLASS);
        }
      });
  }

  private getSortIcon() {
    return this.indicator === 'default' ? 'arrow-down-filled-16' : 'sorting-down-24';
  }

  render() {
    return (
      <Host>
        <div id="container">
          <slot />
          {this.sortable && (
            <div id="sort-icon">
              <groupui-icon name={this.getSortIcon()} class={this.order} />
            </div>
          )}
        </div>
      </Host>
    );
  }
}
